// CheckoutPage.tsx
import React, { useMemo, useState } from "react";
import { CartItem, DeliveryAddress, AddressErrors } from "./types";
import "./CheckoutPage.css";

interface CheckoutPageProps {
  items: CartItem[];
  onBackToCart: () => void;
  onPay: (address: DeliveryAddress) => void;
  isProcessing?: boolean;
}

const FREE_SHIPPING_THRESHOLD = 50;
const FLAT_SHIPPING_FEE = 5.99;

const EMPTY_ADDRESS: DeliveryAddress = {
  fullName: "",
  phone: "",
  addressLine1: "",
  addressLine2: "",
  city: "",
  state: "",
  postalCode: "",
  country: "",
};

const REQUIRED_FIELDS: Array<keyof DeliveryAddress> = [
  "fullName",
  "phone",
  "addressLine1",
  "city",
  "state",
  "postalCode",
  "country",
];

function formatCurrency(amount: number): string {
  return amount.toLocaleString(undefined, {
    style: "currency",
    currency: "USD",
  });
}

function validateAddress(address: DeliveryAddress): AddressErrors {
  const errors: AddressErrors = {};
  for (const field of REQUIRED_FIELDS) {
    if (!address[field].trim()) {
      errors[field] = "This field is required.";
    }
  }
  if (address.phone && !/^[0-9+()\-\s]{7,}$/.test(address.phone.trim())) {
    errors.phone = "Enter a valid phone number.";
  }
  if (address.postalCode && !/^[A-Za-z0-9\- ]{3,10}$/.test(address.postalCode.trim())) {
    errors.postalCode = "Enter a valid postal code.";
  }
  return errors;
}

export default function CheckoutPage({
  items,
  onBackToCart,
  onPay,
  isProcessing = false,
}: CheckoutPageProps) {
  const [address, setAddress] = useState<DeliveryAddress>(EMPTY_ADDRESS);
  const [errors, setErrors] = useState<AddressErrors>({});
  const [touched, setTouched] = useState<Partial<Record<keyof DeliveryAddress, boolean>>>({});

  const subtotal = useMemo(
    () => items.reduce((sum, item) => sum + item.price * item.quantity, 0),
    [items]
  );
  const shipping = subtotal === 0 || subtotal >= FREE_SHIPPING_THRESHOLD ? 0 : FLAT_SHIPPING_FEE;
  const total = subtotal + shipping;

  const handleChange = (field: keyof DeliveryAddress) => (
    event: React.ChangeEvent<HTMLInputElement>
  ) => {
    const value = event.target.value;
    setAddress((prev) => ({ ...prev, [field]: value }));
    if (touched[field]) {
      setErrors((prev) => ({ ...prev, [field]: undefined }));
    }
  };

  const handleBlur = (field: keyof DeliveryAddress) => () => {
    setTouched((prev) => ({ ...prev, [field]: true }));
    setErrors(validateAddress(address));
  };

  const handleSubmit = (event: React.FormEvent) => {
    event.preventDefault();
    const validationErrors = validateAddress(address);
    setErrors(validationErrors);
    setTouched(
      REQUIRED_FIELDS.reduce((acc, field) => ({ ...acc, [field]: true }), {})
    );
    if (Object.keys(validationErrors).length === 0 && items.length > 0) {
      onPay(address);
    }
  };

  const hasItems = items.length > 0;

  return (
    <div className="checkout-page">
      <div className="checkout-header">
        <button
          type="button"
          className="back-button"
          onClick={onBackToCart}
          disabled={isProcessing}
        >
          &larr; Back to cart
        </button>
        <h1 className="checkout-title">Checkout</h1>
      </div>

      <div className="checkout-grid">
        <section className="cart-summary" aria-label="Order summary">
          <h2 className="section-heading">Your items</h2>

          {!hasItems && <p className="empty-cart">Your cart is empty.</p>}

          {hasItems && (
            <ul className="cart-item-list">
              {items.map((item) => (
                <li key={item.id} className="cart-item">
                  <div className="cart-item-image-wrap">
                    {item.imageUrl ? (
                      <img
                        src={item.imageUrl}
                        alt={item.name}
                        className="cart-item-image"
                      />
                    ) : (
                      <div className="cart-item-image placeholder" aria-hidden="true" />
                    )}
                  </div>
                  <div className="cart-item-details">
                    <span className="cart-item-name">{item.name}</span>
                    <span className="cart-item-meta">
                      Qty {item.quantity} &middot; {formatCurrency(item.price)} each
                    </span>
                  </div>
                  <span className="cart-item-line-total">
                    {formatCurrency(item.price * item.quantity)}
                  </span>
                </li>
              ))}
            </ul>
          )}

          <dl className="summary-totals">
            <div className="summary-row">
              <dt>Subtotal</dt>
              <dd>{formatCurrency(subtotal)}</dd>
            </div>
            <div className="summary-row">
              <dt>Shipping</dt>
              <dd>{shipping === 0 ? "Free" : formatCurrency(shipping)}</dd>
            </div>
            <div className="summary-row summary-row-total">
              <dt>Total</dt>
              <dd>{formatCurrency(total)}</dd>
            </div>
          </dl>
        </section>

        <section className="address-section" aria-label="Delivery address">
          <h2 className="section-heading">Delivery address</h2>
          <form className="address-form" onSubmit={handleSubmit} noValidate>
            <div className="field">
              <label htmlFor="fullName">Full name</label>
              <input
                id="fullName"
                type="text"
                autoComplete="name"
                value={address.fullName}
                onChange={handleChange("fullName")}
                onBlur={handleBlur("fullName")}
                className={errors.fullName ? "input-error" : ""}
              />
              {errors.fullName && <span className="field-error">{errors.fullName}</span>}
            </div>

            <div className="field">
              <label htmlFor="phone">Phone number</label>
              <input
                id="phone"
                type="tel"
                autoComplete="tel"
                value={address.phone}
                onChange={handleChange("phone")}
                onBlur={handleBlur("phone")}
                className={errors.phone ? "input-error" : ""}
              />
              {errors.phone && <span className="field-error">{errors.phone}</span>}
            </div>

            <div className="field">
              <label htmlFor="addressLine1">Address line 1</label>
              <input
                id="addressLine1"
                type="text"
                autoComplete="address-line1"
                value={address.addressLine1}
                onChange={handleChange("addressLine1")}
                onBlur={handleBlur("addressLine1")}
                className={errors.addressLine1 ? "input-error" : ""}
              />
              {errors.addressLine1 && (
                <span className="field-error">{errors.addressLine1}</span>
              )}
            </div>

            <div className="field">
              <label htmlFor="addressLine2">Address line 2 (optional)</label>
              <input
                id="addressLine2"
                type="text"
                autoComplete="address-line2"
                value={address.addressLine2}
                onChange={handleChange("addressLine2")}
              />
            </div>

            <div className="form-row">
              <div className="field">
                <label htmlFor="city">City</label>
                <input
                  id="city"
                  type="text"
                  autoComplete="address-level2"
                  value={address.city}
                  onChange={handleChange("city")}
                  onBlur={handleBlur("city")}
                  className={errors.city ? "input-error" : ""}
                />
                {errors.city && <span className="field-error">{errors.city}</span>}
              </div>

              <div className="field">
                <label htmlFor="state">State / Region</label>
                <input
                  id="state"
                  type="text"
                  autoComplete="address-level1"
                  value={address.state}
                  onChange={handleChange("state")}
                  onBlur={handleBlur("state")}
                  className={errors.state ? "input-error" : ""}
                />
                {errors.state && <span className="field-error">{errors.state}</span>}
              </div>
            </div>

            <div className="form-row">
              <div className="field">
                <label htmlFor="postalCode">Postal code</label>
                <input
                  id="postalCode"
                  type="text"
                  autoComplete="postal-code"
                  value={address.postalCode}
                  onChange={handleChange("postalCode")}
                  onBlur={handleBlur("postalCode")}
                  className={errors.postalCode ? "input-error" : ""}
                />
                {errors.postalCode && (
                  <span className="field-error">{errors.postalCode}</span>
                )}
              </div>

              <div className="field">
                <label htmlFor="country">Country</label>
                <input
                  id="country"
                  type="text"
                  autoComplete="country-name"
                  value={address.country}
                  onChange={handleChange("country")}
                  onBlur={handleBlur("country")}
                  className={errors.country ? "input-error" : ""}
                />
                {errors.country && <span className="field-error">{errors.country}</span>}
              </div>
            </div>

            <button
              type="submit"
              className="pay-button"
              disabled={!hasItems || isProcessing}
            >
              {isProcessing ? "Processing…" : `Pay ${formatCurrency(total)}`}
            </button>
          </form>
        </section>
      </div>
    </div>
  );
}
```

